public func eprint<T>(arg: T, flush!: Bool = false): Unit where T <: ToString 功能：将指定 T 类型实例的字符串表示打印到标准错误文本流。 如抛出异常时，消息将打印到标准错误文本流（stderr），而不是标准输出（stdout）。 参数： arg: T - 待打印的 T 类型实例，该函数将打印其 toString 的返回值。 flush!: Bool - 是否清空缓存，true 清空，false 不清空，默认 false。 示例： class Rectangle <: ToString{ var width: Int64 var height: Int64 public init(width: Int64, height: Int64) { this.width = width this.height = height } public func area() { width * height } public func toString(): String{ return "width: ${this.width}, height: ${this.height}" }
} main() { try { throw NegativeArraySizeException("I am an Exception!") } catch (e: NegativeArraySizeException) { eprint<Rectangle>(Rectangle(10,20), flush: true) }
} 运行结果： width: 10, height: 20

