public func max<T>(a: T, b: T, others: Array<T>): T where T <: Comparable<T> 功能：根据 T 类型的 Comparable 接口实现，返回一组数据中的最大值，由于此函数的第三个参数是一个变长参数，支持获取二个以上的数据的比较。 注意： 浮点数类型的比较也将按照 Comparable 的结果进行比较，如果浮点书中有非数 NaN，结果将不正确，此时建议使用 Float16 、 Float32 、 Float64 的 static func max方法。 参数： a: T - 第一个待比较的数。 b: T - 第二个待比较的数。 others: Array <T> - 其他待比较的数。 返回值： T - 返回参数中的最大值。 示例： class Rectangle <: Comparable<Rectangle> & ToString{ var width: Int64 var height: Int64 public init(width: Int64, height: Int64) { this.width = width this.height = height } public prop area: Int64 { get() { return this.width * this.height } } public func compare(t: Rectangle): Ordering { if (t.area > this.area) { return Ordering.LT } else if (t.area == this.area) { return Ordering.EQ } else { Ordering.GT } } public func toString(): String{ return "width: ${this.width}, height: ${this.height}, area: ${this.area}" }
}
