import std.database.sql.*
import std.time.* main() { let SQL_INSERT = "INSERT INTO EMPLOYEE (NAME, SALARY, CREATED_DATE) VALUES (?, ?, ?)" let drv = DriverManager.getDriver("opengauss") ?? return let db = drv.open("opengauss://localhost:5432/testdb") try(cn = db.connect()) { let psInsert = cn.prepareStatement(SQL_INSERT) // 创建事务对象 let tx = cn.createTransaction() try { // 插入第一条数据 psInsert.set<String>(0, "mkyong") psInsert.set<Array<Byte>>(1, Array<Byte>(1, repeat: 10)) psInsert.set<DateTime>(2, DateTime.now()) psInsert.update() // 插入第二条数据 psInsert.set<String>(0, "kungfu") psInsert.set<Array<Byte>>(1, Array<Byte>(1, repeat: 20)) psInsert.set<DateTime>(2, DateTime.now()) psInsert.update() // 如果连接到数据库，测试回滚 SQLException：未为参数3指定值。 psInsert.set<String>(0, "mkyong") psInsert.set<Array<Byte>>(1, Array<Byte>(5, {i => UInt8(i + 1)})) psInsert.update() // 提交事务 tx.commit() } catch (e1: SqlException) { e1.printStackTrace() try { // 发生异常，回滚所有事务 tx.rollback() } catch (e2: SqlException) { // 如果回滚失败 e2.printStackTrace() } } } catch (e: SqlException) { // 如果连接失败 e.printStackTrace() }
