public func slice(start: Int64, len: Int64): Array<T> 功能：获取数组切片。 注意： 切片不会对数组数据进行拷贝，是对原数据特定区间的引用。 参数： start: Int64 - 切片的起始位置，取值需大于 0，且 start + len 小于等于当前 Array 实例的长度。 len: Int64 - 切片的长度，取值需大于 0。 返回值： Array <T> - 返回切片后的数组。 异常： IndexOutOfBoundsException - 如果参数不符合上述取值范围，抛出异常。 示例： class Rectangle <: ToString { var width: Int64 var height: Int64 public init(width: Int64, height: Int64) { this.width = width this.height = height } public func toString(): String { return "width: ${this.width}, height: ${this.height}" }
} main(): Int64 { let arr = [Rectangle(1, 2), Rectangle(3, 4), Rectangle(5, 6)] let arr1 = arr.slice(1, 2) println(arr1) /* 由于 slice() 是对原数组的引用，在新数组上修改，原数组引用类型的元素也会变化 */ arr1[0].width = 5 println(arr) return 0
} 运行结果： [width: 3, height: 4, width: 5, height: 6]
[width: 1, height: 2, width: 5, height: 4, width: 5, height: 6]

