public func sort<T>(data: Array<T>, stable!: Bool = false, descending!: Bool = false): Unit where T <: Comparable<T> 功能：对数组进行排序。可根据入参指定是否要进行稳定排序，是升序还是降序。 参数： data: Array <T> - 需要排序的数组。 stable!: Bool - 是否使用稳定排序，默认为否。 descending!: Bool - 是否使用降序排序，默认为否。 示例： import std.sort.* class Rectangle <: Comparable<Rectangle> & ToString { var width: Int64 var height: Int64 public init(width: Int64, height: Int64) { this.width = width this.height = height } public func compare(r: Rectangle) { let tValue: Int64 = this.width * this.height let rValue: Int64 = r.width * r.height if (tValue > rValue) { return Ordering.GT } else if (tValue == rValue) { return Ordering.EQ } else { return Ordering.LT } } public func toString(): String { return "#width: ${this.width}, height: ${this.height}" }
} main() { /* 按照面积降序排序 */ var arr = [Rectangle(4, 8), Rectangle(6, 7), Rectangle(2, 6)] sort<Rectangle>(arr, stable: true, descending: true) println(arr) return 0
