框架的核心算法可以用以下伪代码表示： // 由@Bench[arg in dataStrategy] 宏在 someFunc(arg: Arg) 函数上生成 let measurement = TimeNow() // 或者使用通过 @Measure 宏提供的其他 Measurement 实现
func measureBatchSomeFunc( parameter: ImmutableInputProvider<Arg>, // 或任何由策略返回的其他 BenchInputProvider 实现 batchSize: Int64, maxBatchSize: Int64,
): Float64 { parameter.reset(maxBatchSize) // 如果需要批量预生成输入数据，则重置 BatchInputProvider measurement.setup() let start = measurement.measure() for(i in 0..maxBatchSize) { // 循环始终执行到 maxBatchSize，这样我们可以将循环本身所需的时间从最终结果中排除 let arg = parameter.get(i) if (i < batchSize) { /* body of someFunc */ } } measurement.measure() - start
}
Framework.addBenchmark(dataStrategy, Benchmark(measureBatchSomeFunc)) // 框架内部 for (data in dataStrategy) { benchmark.runBench(data)
} doStatisticalAnalisys(benchmark.results) class Benchmark<T> { let results = ArrayList<(BatchSize, BatchResult)> Benchmark(let runBatch: (T, Int64, Int64) -> Float64) {} func runBench(data: T) { let estimation = warmup(data) let batchSizes = calcBatchSizes(estimation) for (i in batchSizes) { let resultBatch = runBatch(data, i, batchSizes.end) results.append(i, resultBatch) // 根据explicitGC配置参数运行GC explicitGC.invoke() } } func warmup(data: T) { // 根据 warmup 配置参数进行预热 } func calcBatchSizes(estimation: Duration) { // 根据预热估计选择最合适的批处理量和批处理大小 } } 这里的主要逻辑是，measureBatchSomeFunc(data, i, maxBatchSize) 和 measureBatchSomeFunc(data, i+n, maxBatchSize) 的执行时间差正好是执行 n 次 someFunc 的时间。 这意味着，通过估算这两次执行时间的差异，我们可以精确地估算出单次执行 someFunc 所需的时间。而这样的估算不包括测试本身、批量循环或获取下一份输入数据所带来的开销。

