for (i in 0..4) { foo.bar(i % 2)
} // 验证 bar() 在传入参数为 0 或 1 的情况下均至少执行一次
Verify.unordered( @Called(foo.bar(0)), @Called(foo.bar(1))
) // 此处的验证动作将抛出异常，因为 `foo.bar(_)` 包含了 `foo.bar(1)`
Verify.unordered( @Called(foo.bar(_)).times(2), @Called(foo.bar(1)).times(2)
)
// 可以通过如下方式进行验证
// 验证入参为 1 的调用表达式执行了2次
