} class MyClass<T> { var myData: Array<T> public init() { // 用 zeroValue<T>() 对 Array 进行全零初始化 myData = Array<T>(10, repeat: unsafe { zeroValue<T>() }) } public func get(index: Int64): T { myData[index] } public func set(index: Int64, element: T): Unit { myData[index] = element }
}
class Student <: ToString { public func toString() { "student" }
} 示例结果： student

