extend<T> CPointer<T> 功能：为 CPointer <T> 扩展一些必要的指针使用相关接口，包含判空、读写数据等接口。 其中泛型 T 为指针类型，其满足 CType 约束。对 CPointer 做运算需要在 unsafe 上下文中进行。 func asResource() public func asResource(): CPointerResource<T> 功能：获取该指针 CPointerResource 实例，该实例可以在 try-with-resource 语法上下文中实现内容自动释放。 返回值： CPointerResource <T> - 当前指针对应的 CPointerResource 实例。 示例： foreign func malloc(size: UIntNative): CPointer<Unit> main() { let sizeofInt64: UIntNative = 8 var p1 = unsafe { malloc(sizeofInt64) } var ptr = unsafe { CPointer<Int64>(p1) } unsafe { ptr.write(10) } var ptrResource: CPointerResource<Int64> = ptr.asResource() try (r = ptrResource) { var p = r.value let num: Int64 = unsafe { p.read() } println(num) } println(ptrResource.isClosed())
} 运行结果： 10
true func isNotNull() public func isNotNull(): Bool 功能：判断指针是否不为空。 返回值： Bool - 如果不为空返回 true，否则返回 false。 示例： foreign func malloc(size: UIntNative): CPointer<Unit>
foreign func free(ptr: CPointer<Unit>): Unit main() { let p1 = CPointer<Int64>() println(p1.isNotNull()) let sizeofInt64: UIntNative = 8 var p2 = unsafe { malloc(sizeofInt64) } println(p2.isNotNull()) unsafe { free(p2) }
} 运行结果： false
true func isNull() public func isNull(): Bool 功能：判断指针是否为空。 返回值： Bool - 如果为空返回 true，否则返回 false。 示例： foreign func malloc(size: UIntNative): CPointer<Unit> foreign func free(ptr: CPointer<Unit>): Unit main() { let sizeofInt64: UIntNative = 8 var p1 = unsafe { malloc(sizeofInt64) } var ptr = unsafe { CPointer<Int64>(p1) } unsafe { ptr.write(10) } let num: Int64 = unsafe { ptr.read() } println(num) unsafe { free(p1) }
} 运行结果： 10 func read() public unsafe func read(): T 功能：读取第一个数据，该接口需要用户保证指针的合法性，否则发生未定义行为。 返回值： T - 该对象类型的第一个数据。 示例： foreign func malloc(size: UIntNative): CPointer<Unit>
foreign func free(ptr: CPointer<Unit>): Unit main() { let p1 = CPointer<Int64>() println(p1.isNull()) let sizeofInt64: UIntNative = 8 var p2 = unsafe { malloc(sizeofInt64) } println(p2.isNull()) unsafe { free(p2) }
} 运行结果： true
false func read(Int64) public unsafe func read(idx: Int64): T 功能：根据下标读取对应的数据，该接口需要用户保证指针的合法性，否则发生未定义行为。 参数： idx: Int64 - 要获取数据的下标。 返回值： T - 输入下标对应的数据。 示例： main() { var arr: Array<Int64> = [1, 2, 3, 4] var cptrHandle: CPointerHandle<Int64> = unsafe { acquireArrayRawData(arr) } var cptr: CPointer<Int64> = cptrHandle.pointer let num: Int64 = unsafe { cptr.read(2) } println("The third element of the array is ${num} ") unsafe { releaseArrayRawData<Int64>(cptrHandle) }
} 运行结果： The third element of the array is 3 func toUIntNative() public func toUIntNative(): UIntNative 功能：获取该指针的整型形式。 返回值： UIntNative - 该指针的整型形式。 示例： foreign func malloc(size: UIntNative): CPointer<Unit> foreign func free(ptr: CPointer<Unit>): Unit main() { let sizeofInt64: UIntNative = 8 var p = unsafe { malloc(sizeofInt64) } var p1 = unsafe { CPointer<Int64>(p) } unsafe { p1.write(8) } println(p1.toUIntNative()) unsafe { free(p) }
} 运行结果： 93954490863648 func write(Int64, T) public unsafe func write(idx: Int64, value: T): Unit 功能：在指定下标位置写入一个数据，该接口需要用户保证指针的合法性，否则发生未定义行为。 参数： idx: Int64 - 指定的下标位置。 value: T - 写入的数据。 示例： main() { var arr: Array<Int64> = [1, 2, 3, 4] var cptrHandle: CPointerHandle<Int64> = unsafe { acquireArrayRawData(arr) } var cptr: CPointer<Int64> = cptrHandle.pointer unsafe { cptr.write(2, 6) } println("The third element of the array is ${arr[2]} ") // The first element of the array is 1 unsafe { releaseArrayRawData<Int64>(cptrHandle) }
} 运行结果： The third element of the array is 6 func write(T) public unsafe func write(value: T): Unit 功能：写入一个数据，该数据总是在第一个，该接口需要用户保证指针的合法性，否则发生未定义行为。 参数： value: T - 要写入的数据。 示例： foreign func malloc(size: UIntNative): CPointer<Unit>
foreign func free(ptr: CPointer<Unit>): Unit main() { let sizeofInt64: UIntNative = 8 var p = unsafe { malloc(sizeofInt64) } var p1 = unsafe { CPointer<Int64>(p) } unsafe { p1.write(8) } let value: Int64 = unsafe { p1.read() } println(value) unsafe{ free(p) }
} 运行结果： 8 operator func +(Int64) public unsafe operator func +(offset: Int64): CPointer<T> 功能： CPointer 对象指针后移，同 C 语言的指针加法操作。 参数： offset: Int64 - 偏移量。 返回值： CPointer <T> - 返回偏移后的指针。 示例： main() { var arr: Array<Int64> = [1, 2, 3, 4] var cptrHandle: CPointerHandle<Int64> = unsafe { acquireArrayRawData(arr) } var cptr: CPointer<Int64> = cptrHandle.pointer let num1: Int64 = unsafe { cptr.read() } println(num1) cptr = unsafe { cptr + 1 } let num2: Int64 = unsafe { cptr.read() } println(num2) unsafe { releaseArrayRawData<Int64>(cptrHandle) }
} 运行结果： 1
