extend CString <: ToString 功能：为 CString 类型扩展一些字符串指针常用方法，包括判空、获取长度、判等、获取子串等。 父类型： ToString func asResource() public func asResource(): CStringResource 功能：获取当前 CString 实例对应的 CStringResource C 字符串资源类型实例。 CStringResource 实现了 Resource 接口，可以在 try-with-resource 语法上下文中实现资源自动释放。 返回值： CStringResource - 对应的 CStringResource C 字符串资源类型实例。 示例： foreign func malloc(size: UIntNative): CPointer<Unit> main() { var str: CString = unsafe { LibC.mallocCString("hello") } var ptrResource: CStringResource = str.asResource() try (r = ptrResource) { var p = r.value println(p.size()) } println(ptrResource.isClosed())
} 运行结果： 5
true func compare(CString) public func compare(str: CString): Int32 功能：按字典序比较两个字符串，同 C 语言中的 strcmp。 参数： str: CString - 比较的目标字符串。 返回值： Int32 - 两者相等返回 0，如果当前字符串比参数 str 小，返回 -1，否则返回 1。 异常： Exception - 如果被比较的两个 CString 中存在空指针，抛出异常。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = unsafe { LibC.mallocCString("hello") } println(str1.compare(str2)) var str3: CString = unsafe { LibC.mallocCString("hello") } var str4: CString = unsafe { LibC.mallocCString("hellow") } println(str3.compare(str4)) var str5: CString = unsafe { LibC.mallocCString("hello") } var str6: CString = unsafe { LibC.mallocCString("allow") } println(str5.compare(str6)) unsafe { LibC.free(str1) LibC.free(str2) LibC.free(str3) LibC.free(str4) LibC.free(str5) LibC.free(str6) }
} 运行结果： 0
-1
1 func endsWith(CString) public func endsWith(suffix: CString): Bool 功能：判断字符串是否包含指定后缀。 参数： suffix: CString - 匹配的目标后缀字符串。 返回值： Bool - 如果该字符串包含 suffix 后缀，返回 true，如果该字符串不包含 suffix 后缀，返回 false，特别地，如果原字符串或者 suffix 后缀字符串指针为空，均返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = unsafe { LibC.mallocCString("lo") } var str3: CString = unsafe { LibC.mallocCString("ao") } println(str1.endsWith(str2)) println(str1.endsWith(str3)) unsafe { LibC.free(str1) LibC.free(str2) LibC.free(str3) }
} 运行结果： true
false func equals(CString) public func equals(rhs: CString): Bool 功能：判断两个字符串是否相等。 参数： rhs: CString - 比较的目标字符串。 返回值： Bool - 如果两个字符串相等，返回 true，否则返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = unsafe { LibC.mallocCString("hello") } var str3: CString = unsafe { LibC.mallocCString("Hello") } println(str1.equals(str2)) println(str1.equals(str3)) unsafe { LibC.free(str1) LibC.free(str2) LibC.free(str3) }
} 运行结果： true
false func equalsLower(CString) public func equalsLower(rhs: CString): Bool 功能：判断两个字符串是否相等，忽略大小写。 参数： rhs: CString - 匹配的目标字符串。 返回值： Bool - 如果两个字符串忽略大小写相等，返回 true，否则返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = unsafe { LibC.mallocCString("HELLO") } var str3: CString = unsafe { LibC.mallocCString("Hello") } println(str1.equalsLower(str2)) println(str1.equalsLower(str3)) unsafe { LibC.free(str1) LibC.free(str2) LibC.free(str3) }
} 运行结果： true
true func getChars() public func getChars(): CPointer<UInt8> 功能：获取该字符串的指针。 返回值： CPointer < UInt8 > - 该字符串的指针。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } var ptr: CPointer<UInt8> = unsafe { str1.getChars() } var c: UInt8 = unsafe { ptr.read() } println(c) // h的ascii码为104 unsafe{ LibC.free(str1) }
} 运行结果： 104 func isEmpty() public func isEmpty(): Bool 功能：判断字符串是否为空字符串。 返回值： Bool - 如果为空字符串或字符串指针为空，返回 true，否则返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } println(str1.isEmpty()) unsafe { LibC.free(str1) }
} 运行结果： false func isNotEmpty() public func isNotEmpty(): Bool 功能：判断字符串是否不为空字符串。 返回值： Bool - 如果不为空字符串，返回 true，如果字符串指针为空，返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } println(str1.isNotEmpty()) unsafe { LibC.free(str1) }
} 运行结果： true func isNull() public func isNull(): Bool 功能：判断字符串指针是否为空。 返回值： Bool - 如果字符串指针为空，返回 true，否则返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } println(str1.isNull()) unsafe { LibC.free(str1) }
} 运行结果： false func size() public func size(): Int64 功能：返回该字符串长度，同 C 语言中的 strlen。 返回值： Int64 - 字符串长度。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } println(str1.size()) unsafe { LibC.free(str1) }
} 运行结果： 5 func startsWith(CString) public func startsWith(prefix: CString): Bool 功能：判断字符串是否包含指定前缀。 参数： prefix: CString - 匹配的目标前缀字符串。 返回值： Bool - 如果该字符串包含 prefix 前缀，返回 true，如果该字符串不包含 prefix 前缀，返回 false，特别地，如果原字符串或者 prefix 前缀字符串指针为空，均返回 false。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = unsafe { LibC.mallocCString("he") } println(str1.startsWith(str2)) unsafe { LibC.free(str1) LibC.free(str2) }
} 运行结果： true func subCString(UIntNative) public func subCString(beginIndex: UIntNative): CString 功能：截取指定位置开始至字符串结束的子串。 注意： 该接口返回为字符串的副本，返回的子串使用完后需要手动 free。 如果 beginIndex 与字符串长度相等，将返回空指针。 参数： beginIndex: UIntNative - 截取的起始位置，取值范围为 [0, this.size()]。 返回值： CString - 截取的子串。 异常： IndexOutOfBoundsException - 如果 beginIndex 大于字符串长度，抛出异常。 IllegalMemoryException - 如果内存申请失败或内存拷贝失败时，抛出异常。 示例： main() { let index: UIntNative = 2 var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = str1.subCString(index) println(str2) unsafe { LibC.free(str1) LibC.free(str2) }
} 运行结果： llo func subCString(UIntNative, UIntNative) public func subCString(beginIndex: UIntNative, subLen: UIntNative): CString 功能：截取字符串的子串，指定起始位置和截取长度。 如果截取的末尾位置超出字符串长度，截取至字符串末尾。 注意： 该接口返回为字符串的副本，返回的子串使用完后需要手动 free。 如果 beginIndex 等于于字符串长度，或 subLen 等于 0，返回空指针。 参数： beginIndex: UIntNative - 截取的起始位置，取值范围为 [0, this.size()]。 subLen: UIntNative - 截取长度，取值范围为 [0, UIntNative .Max]。 返回值： CString - 截取的子串。 异常： IndexOutOfBoundsException - 如果 beginIndex 大于字符串长度，抛出异常。 IllegalMemoryException - 如果内存申请失败或内存拷贝失败时，抛出异常。 示例： main() { let index: UIntNative = 2 let len: UIntNative = 2 var str1: CString = unsafe { LibC.mallocCString("hello") } var str2: CString = str1.subCString(index, len) println(str2) unsafe { LibC.free(str1) LibC.free(str2) }
} 运行结果： ll func toString() public func toString(): String 功能：将 CString 类型转为仓颉的 String 类型。 返回值： String - 转换后的字符串。 异常： IllegalArgumentException - 不合法的 UTF-8 字节序列。 示例： main() { var str1: CString = unsafe { LibC.mallocCString("hello") } println(str1.toString()) unsafe { LibC.free(str1) }
} 运行结果： hello

